#!/usr/bin/env bun
import { existsSync } from "node:fs";
import { DEFAULT_BUDGET } from "../lib/constants";
import { buildEagerContext } from "../lib/inject/eager";
import { appendInjectLog } from "../lib/inject/log";
import { resolveInjectMode } from "../lib/inject/modes";
import { buildPointerPayload } from "../lib/inject/pointer";
import { byteLength } from "../lib/bytes";
import { buildNudgeLine } from "../lib/session-state";
import { resolveVaultPath as resolveProjectVaultPath } from "../lib/vault";

function resolveVaultPath(argv: string[]): string {
  const arg = argv[0];
  if (arg) return arg;
  const env = process.env.KB_VAULT;
  if (env) return env;
  return resolveProjectVaultPath(process.cwd());
}

const DEFAULT_EVENT_NAME = "SessionStart";
// Pin the contract to the events this hook is registered for (hooks.json);
// anything else on stdin is treated as garbage.
const ALLOWED_EVENT_NAMES = new Set(["SessionStart", "PostCompact"]);

// Remembered for the top-level fail-soft path so a crash after event-name
// resolution still reports the real firing event.
let resolvedEventName = DEFAULT_EVENT_NAME;

/**
 * Claude Code hooks receive a JSON payload on stdin whose hook_event_name
 * identifies the firing event (SessionStart or PostCompact here). Tolerant
 * and non-blocking: TTY, absent, slow, or garbled stdin falls back to
 * SessionStart. The timer is cleared after the race so it never holds the
 * event loop open past emit.
 */
async function readHookEventName(): Promise<string> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    if (process.stdin.isTTY) return DEFAULT_EVENT_NAME;
    const text = await Promise.race([
      Bun.stdin.text(),
      new Promise<string>((resolve) => {
        timer = setTimeout(() => resolve(""), 250);
      }),
    ]);
    const parsed = JSON.parse(text) as { hook_event_name?: unknown };
    return typeof parsed.hook_event_name === "string" &&
      ALLOWED_EVENT_NAMES.has(parsed.hook_event_name)
      ? parsed.hook_event_name
      : DEFAULT_EVENT_NAME;
  } catch {
    return DEFAULT_EVENT_NAME;
  } finally {
    if (timer !== undefined) clearTimeout(timer);
  }
}

function emitEmpty(eventName: string): void {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: eventName,
        additionalContext: "",
      },
    }) + "\n"
  );
}

function emitContext(eventName: string, context: string): void {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: eventName,
        additionalContext: context,
      },
    }) + "\n"
  );
}

function countAdvertised(payload: string): number {
  const line = payload.split("\n").find((l) => l.startsWith("Topics:"));
  if (!line) return 0;
  return line
    .replace(/^Topics:\s*/, "")
    .replace(/\.\s*$/, "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean).length;
}

let emitted = false;

function emitOnce(eventName: string, context: string): void {
  if (emitted) return;
  emitted = true;
  emitContext(eventName, context);
}

function emitEmptyOnce(eventName: string): void {
  if (emitted) return;
  emitted = true;
  emitEmpty(eventName);
}

async function main(): Promise<void> {
  const eventName = await readHookEventName();
  resolvedEventName = eventName;
  const vaultPath = resolveVaultPath(process.argv.slice(2));
  const parsedBudget = Number(process.env.KB_BUDGET ?? DEFAULT_BUDGET);
  const budget =
    Number.isFinite(parsedBudget) && parsedBudget > 0 ? parsedBudget : DEFAULT_BUDGET;

  if (!existsSync(vaultPath)) {
    emitEmptyOnce(eventName);
    return;
  }

  let mode: ReturnType<typeof resolveInjectMode>;
  try {
    mode = resolveInjectMode(vaultPath, process.env.KB_INJECT_MODE);
  } catch {
    mode = "eager";
  }

  let context = "";
  let advertised = 0;
  try {
    if (mode === "off") {
      context = "";
    } else {
      const nudge = buildNudgeLine(vaultPath);
      if (mode === "lazy") {
        context = buildPointerPayload({ vaultPath, nudge });
        advertised = countAdvertised(context);
      } else {
        context = buildEagerContext({ vaultPath, budget, nudge });
      }
    }
  } catch {
    context = "";
  }

  emitOnce(eventName, context);

  try {
    await appendInjectLog(vaultPath, {
      timestamp: new Date().toISOString(),
      event: "inject",
      mode,
      bytes: byteLength(context),
      categories_advertised: advertised,
    });
  } catch {
    // logging must never fail the hook
  }
}

main().catch(() => {
  emitEmptyOnce(resolvedEventName);
  process.exit(0);
});
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { byteLength } from "../bytes";

export interface EagerInput {
  vaultPath: string;
  budget: number;
  /** Optional one-line nudge, appended after sessions content within budget. */
  nudge?: string | null;
}

function readSafely(path: string): string | null {
  try {
    return readFileSync(path, "utf-8");
  } catch {
    return null;
  }
}

function appendIfFits(current: string, section: string, budget: number): string {
  const candidate = current ? `${current}\n\n${section}` : section;
  return byteLength(candidate) <= budget ? candidate : current;
}

export function buildEagerContext({ vaultPath, budget, nudge }: EagerInput): string {
  // Reserve the nudge before fitting content, mirroring the lazy pointer:
  // without the reservation the nudge is sacrificed first on full vaults —
  // exactly when sessions pile up and the nudge matters most. Eligibility is
  // judged on the bare nudge (when nothing else fits, it is emitted without
  // a separator); the separator bytes are reserved only against content.
  const effectiveNudge = nudge && byteLength(nudge) <= budget ? nudge : null;
  if (effectiveNudge) budget = Math.max(0, budget - byteLength(`\n\n${effectiveNudge}`));

  let ctx = "";

  const contextBody = readSafely(join(vaultPath, "context.md"));
  if (contextBody !== null) {
    ctx = appendIfFits(
      ctx,
      `## KB Vault Context\n\nVerify against codebase before acting on any recalled facts.\n\n### Working Set\n${contextBody}`,
      budget
    );
  }

  const indexBody = readSafely(join(vaultPath, "index.md"));
  if (indexBody !== null) {
    const section = ctx
      ? `### Index\n${indexBody}`
      : `## KB Vault Context\n\nVerify against codebase before acting on any recalled facts.\n\n### Index\n${indexBody}`;
    ctx = appendIfFits(ctx, section, budget);
  }

  const sessionsDir = join(vaultPath, "sessions");
  if (existsSync(sessionsDir)) {
    let files: string[];
    try {
      files = readdirSync(sessionsDir)
        .filter((f) => f.endsWith(".md"))
        .sort()
        .reverse();
    } catch {
      files = [];
    }
    const summariesDir = join(sessionsDir, "summaries");
    let headerAdded = false;
    for (const f of files) {
      const summaryBody = readSafely(join(summariesDir, f));
      const body = summaryBody ?? readSafely(join(sessionsDir, f));
      if (body === null) continue;
      const section = headerAdded
        ? `\n---\n${body}`
        : `\n### Recent Sessions\n---\n${body}`;
      const next = appendIfFits(ctx, section, budget);
      if (next === ctx) break;
      ctx = next;
      headerAdded = true;
    }
  }

  if (effectiveNudge) ctx = ctx ? `${ctx}\n\n${effectiveNudge}` : effectiveNudge;

  return ctx;
}
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { byteLength } from "../bytes";

const POINTER_BUDGET = 500;
const MAX_CATEGORIES = 8;
const HEADING_RE = /^##\s+(.+?)\s*$/gm;

function extractCategories(indexMd: string): string[] {
  const out: string[] = [];
  const matches = indexMd.matchAll(HEADING_RE);
  for (const m of matches) {
    const name = m[1]?.trim();
    if (name) out.push(name);
  }
  return out;
}

export interface PointerInput {
  vaultPath: string;
  /** Optional one-line nudge, reserved inside POINTER_BUDGET before topic fitting. */
  nudge?: string | null;
}

function readIndexSafely(indexPath: string): string {
  try {
    return readFileSync(indexPath, "utf-8");
  } catch {
    return "";
  }
}

export function buildPointerPayload({ vaultPath, nudge }: PointerInput): string {
  const indexPath = join(vaultPath, "index.md");
  const categories: string[] = existsSync(indexPath)
    ? extractCategories(readIndexSafely(indexPath))
    : [];

  const header =
    "## KB Vault\n" +
    "Curated memory available. Do not read sessions/ or raw/ directly.\n" +
    "Run `kb map <query>` to find knowledge; `kb recall <query>` only as plain-text fallback.";

  // The nudge is reserved before topic fitting: topics shrink to make room so
  // the payload keeps the POINTER_BUDGET invariant.
  const suffix = nudge ? `\n${nudge}` : "";

  if (categories.length === 0) return `${header}${suffix}`;

  let rendered = `${header}${suffix}`;
  for (let n = Math.min(categories.length, MAX_CATEGORIES); n >= 1; n--) {
    const topics = categories.slice(0, n).join(", ");
    const candidate = `${header}\n\nTopics: ${topics}.${suffix}`;
    if (byteLength(candidate) <= POINTER_BUDGET) {
      rendered = candidate;
      break;
    }
  }

  return rendered;
}
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

export type InjectMode = "eager" | "lazy" | "off";

const VALID_MODES: ReadonlySet<InjectMode> = new Set(["eager", "lazy", "off"]);

function parseMode(value: unknown): InjectMode | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase();
  return VALID_MODES.has(normalized as InjectMode) ? (normalized as InjectMode) : null;
}

export function resolveInjectMode(vaultPath: string, envValue: string | undefined): InjectMode {
  const fromEnv = parseMode(envValue);
  if (fromEnv) return fromEnv;

  const configPath = join(vaultPath, ".kb", "config.json");
  if (existsSync(configPath)) {
    try {
      const raw = readFileSync(configPath, "utf-8");
      const parsed = JSON.parse(raw) as { inject_mode?: unknown };
      const fromConfig = parseMode(parsed.inject_mode);
      if (fromConfig) return fromConfig;
    } catch {
      // fall through to default
    }
  }

  return "eager";
}
#!/usr/bin/env bash
# KB injection hook — SessionStart and PostCompact
# Delegates to the TypeScript implementation for mode-aware injection
# (eager | lazy | off), pointer payloads, and inject logging.
#
# Fail-soft: if bun is missing or the TS hook errors, emit an empty
# context envelope so SessionStart does not break.

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"

# Capture the hook payload (Claude Code pipes JSON on stdin) so both the
# fallback and the TS hook can read the firing event's name. Skip on a TTY
# so manual runs don't block.
STDIN_JSON=""
if [ ! -t 0 ]; then
  STDIN_JSON="$(cat 2>/dev/null || true)"
fi

EVENT_NAME="$(printf '%s' "$STDIN_JSON" | sed -n 's/.*"hook_event_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')"
# Allowlist: only the events this hook registers for; anything else (including
# backslash-bearing or spoofed matches that would break the printf'd JSON)
# falls back to SessionStart.
case "$EVENT_NAME" in
  SessionStart|PostCompact) ;;
  *) EVENT_NAME="SessionStart" ;;
esac

emit_empty() {
  printf '{"hookSpecificOutput":{"hookEventName":"%s","additionalContext":""}}\n' "$EVENT_NAME"
}

if ! command -v bun >/dev/null 2>&1; then
  emit_empty
  exit 0
fi

if ! printf '%s' "$STDIN_JSON" | bun "${SCRIPT_DIR}/../src/hooks/inject.ts" "$@"; then
  emit_empty
  exit 0
fi
#!/usr/bin/env bash
# KB session capture hook — Stop event
set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_ROOT="${CLAUDE_PLUGIN_ROOT:-$(cd "${SCRIPT_DIR}/.." && pwd)}"
VAULT_PATH="${KB_VAULT:-${HOME}/kb}"

if command -v bun >/dev/null 2>&1; then
  BUN_BIN="bun"
elif [ -x "${HOME}/.bun/bin/bun" ]; then
  BUN_BIN="${HOME}/.bun/bin/bun"
else
  mkdir -p "${VAULT_PATH}/.kb"
  printf '{"ts":"%s","stage":"bash","reason":"bun-not-found"}\n' "$(date -u +"%Y-%m-%dT%H:%M:%SZ")" >> "${VAULT_PATH}/.kb/capture-errors.log"
  exit 0
fi

"${BUN_BIN}" "${PLUGIN_ROOT}/src/cli.ts" capture-session || true
exit 0

