            line_range: [1, lines.length],
            curation: "curated",
            text: body,
          },
        ],
      })
    );
    process.stdout.write(wire);

    try {
      await appendAccessLog({
        vaultPath,
        command: "get",
        query: pageArg,
        pages_returned: 1,
        bytes_returned: new TextEncoder().encode(wire).length,
