      }

      if (!flags.session) throw new Error("usage: kb summarize [--json] [--force] <session>");
      const result = await summarizeSession(vaultPath, flags.session, {
        force: flags.force,
        destructive: flags.destructive,
      });

      if (flags.json) {
        console.log(JSON.stringify(result));
