  observations.push(JSON.parse(JSON.stringify(observation).replaceAll(fixture.root, "<fixture>")));
  console.log(`${observation.pass ? "PASS" : "FAIL"} ${id}`);
  rmSync(fixture.root, { recursive: true, force: true });
}

