  if (typeof content === "string") {
    return { turn: content.trim().length > 0 ? { role, text: content } : null, malformed: false };
  }
  if (!Array.isArray(content)) return { turn: null, malformed: true };

  const text: string[] = [];
  let malformed = false;
  for (const part of content) {
    if (!isRecord(part)) {
