 for(const name of ['answer.md','activity.md','commands.jsonl','solve.json'])writeFileSync(join(destination,name),normalize(readFileSync(join(trial.root,name),'utf8')));
 writeFileSync(join(destination,'knowledge-hashes.json'),JSON.stringify({before,after,changes,unauthorized},null,2)+'\n');
 const skill=readFileSync(task.skill_path,'utf8');
 observations.push({version:trial.version,id:trial.id,prompt:task.scenario.prompt,expected:task.scenario.expected,allowed_knowledge_writes:allowed,answer:normalize(readFileSync(join(trial.root,'answer.md'),'utf8')),activity:normalize(readFileSync(join(trial.root,'activity.md'),'utf8')),skill_sha256:createHash('sha256').update(skill).digest('hex'),commands:commands.map(c=>({args:c.args,exit_code:c.exit_code,stdout_bytes:c.stdout_bytes,elapsed_ms:c.elapsed_ms})),metrics:{cli_calls:commands.length,cli_stdout_bytes:commands.reduce((s,c)=>s+c.stdout_bytes,0)},knowledge_changes:changes,unauthorized_knowledge_changes:unauthorized,artifact_dir:destination});
}
const report={kind:'actual-agent-trials',conditions:{harness:'Codex child agents with fresh context per trial',model:'inherited serving model; exact identifier/version not exposed by collaboration API',tools:'shell and file tools only by task instruction; CLI execution recorded by wrapper',os_sandbox_enforced:false,native_hooks:false,mcp:false,qmd:false,summary_provider:'deterministic local fixture',trials_per_condition:1,expected_outcomes_withheld:true,fixture_factory:'evals/fixtures.ts',token_cost_metrics:'not exposed; no token/cost savings claimed'},baseline_sha:paths.base_sha,pending,observations};
writeFileSync(join(plan,'reports/A1-agent-trials.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({finished:observations.length,pending,observations:observations.map(o=>({version:o.version,id:o.id,...o.metrics,unauthorized:o.unauthorized_knowledge_changes}))},null,2));
JS",max_output_tokens:3000}));

