const plan='docs/plans/2026-10-16-portable-agent-workflows';const paths=JSON.parse(readFileSync(join(plan,'evidence/agent-trial-paths.json'),'utf8'));const report=JSON.parse(readFileSync(join(plan,'reports/A1-agent-trials.json'),'utf8'));const t=paths.trials.find(t=>t.version==='current'&&t.id==='A18-unsupported-transcript');const task=JSON.parse(readFileSync(join(t.root,'task.json'),'utf8'));const after=knowledgeSnapshot(task.vault),before=task.before_knowledge_sha256;const changes=[...new Set([...Object.keys(before),...Object.keys(after)])].sort().filter(p=>before[p]!==after[p]);const unauthorized=changes.filter(p=>!task.scenario.allowed_knowledge_writes.includes(p));const commands=readFileSync(join(t.root,'commands.jsonl'),'utf8').trim().split('\n').map(JSON.parse);const dest=join(plan,'evidence/agent-trials/current',t.id);mkdirSync(dest,{recursive:true});const norm=s=>s.replaceAll(t.root,'<fixture>').replaceAll(paths.current,'<current-source>');for(const name of ['answer.md','activity.md','commands.jsonl','solve.json'])writeFileSync(join(dest,name),norm(readFileSync(join(t.root,name),'utf8')));writeFileSync(join(dest,'knowledge-hashes.json'),JSON.stringify({before,after,changes,unauthorized},null,2)+'\n');report.observations.push({version:t.version,id:t.id,prompt:task.scenario.prompt,expected:task.scenario.expected,allowed_knowledge_writes:task.scenario.allowed_knowledge_writes,answer:norm(readFileSync(join(t.root,'answer.md'),'utf8')),activity:norm(readFileSync(join(t.root,'activity.md'),'utf8')),skill_sha256:createHash('sha256').update(readFileSync(join(plan,'evidence/agent-instructions/current-initial/skills/kb/SKILL.md'))).digest('hex'),commands:commands.map(c=>({args:c.args,exit_code:c.exit_code,stdout_bytes:c.stdout_bytes,elapsed_ms:c.elapsed_ms})),metrics:{cli_calls:commands.length,cli_stdout_bytes:commands.reduce((s,c)=>s+c.stdout_bytes,0)},knowledge_changes:changes,unauthorized_knowledge_changes:unauthorized,artifact_dir:dest});report.pending=[];writeFileSync(join(plan,'reports/A1-agent-trials.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({trials:report.observations.length,last:report.observations.at(-1)},null,2));
