import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { knowledgeSnapshot } from './evals/fixtures.ts';
const plan = 'docs/plans/2026-10-16-portable-agent-workflows';
const paths = JSON.parse(readFileSync(`${plan}/evidence/agent-trial-paths.json`, 'utf8'));
const reportPath = `${plan}/reports/A1-agent-trials.json`;
const report = JSON.parse(readFileSync(reportPath, 'utf8'));
report.observations = report.observations.filter(o => o.version !== 'refined');
for (const t of paths.trials.filter(t => t.version === 'refined')) {
  const task = JSON.parse(readFileSync(`${t.root}/task.json`, 'utf8'));
  const solve = JSON.parse(readFileSync(`${t.root}/solve.json`, 'utf8'));
  const before = task.before_knowledge_sha256;
  const after = knowledgeSnapshot(task.vault);
  const changes = [...new Set([...Object.keys(before), ...Object.keys(after)])].filter(k => before[k] !== after[k]).sort();
  const allowed = task.scenario.allowed_knowledge_writes;
  const unauthorized = changes.filter(k => !allowed.some(p => p.endsWith('*') ? k.startsWith(p.slice(0,-1)) : k === p));
  const norm = s => s.replaceAll(t.root, '<fixture>').replaceAll(paths.base, '<baseline-source>').replaceAll(paths.current, '<current-source>');
  const answer = norm(readFileSync(`${t.root}/answer.md`, 'utf8'));
  const activity = norm(readFileSync(`${t.root}/activity.md`, 'utf8'));
  const rawCommands = readFileSync(`${t.root}/commands.jsonl`, 'utf8');
  const commands = rawCommands.trim().split('\n').map(l => JSON.parse(l));
  const dest = `${plan}/evidence/agent-trials/refined/${t.id}`;
  mkdirSync(dest, {recursive:true});
  writeFileSync(`${dest}/answer.md`, answer);
  writeFileSync(`${dest}/activity.md`, activity);
  writeFileSync(`${dest}/commands.jsonl`, norm(rawCommands));
  writeFileSync(`${dest}/solve.json`, norm(JSON.stringify(solve,null,2))+'\n');
  writeFileSync(`${dest}/knowledge-hashes.json`, JSON.stringify({before,after,changes,unauthorized},null,2)+'\n');
  const observation = {version:t.version,id:t.id,prompt:task.scenario.prompt,expected:task.scenario.expected,allowed_knowledge_writes:allowed,answer,activity,skill_sha256:createHash('sha256').update(readFileSync(solve.skill_path)).digest('hex'),commands:commands.map(c => ({args:c.args,exit_code:c.exit_code,stdout_bytes:c.stdout_bytes,elapsed_ms:c.elapsed_ms})),metrics:{cli_calls:commands.length,cli_stdout_bytes:commands.reduce((n,c)=>n+c.stdout_bytes,0)},knowledge_changes:changes,unauthorized_knowledge_changes:unauthorized,artifact_dir:dest};
  report.observations.push(observation);
  console.log(JSON.stringify(observation,null,2));
}
report.pending=[];
report.conditions.revisions = 'base: original; current: initial portable implementation; refined: same implementation with D1 correction 1';
writeFileSync(reportPath, JSON.stringify(report,null,2)+'\n');
