import { resolve } from "node:path";
import { byteLength } from "./bytes";
import { buildEnvelope, writeEnvelope, type EnvelopeChunk, type EnvelopePolicy } from "./envelope";

const DEFAULT_RETRIEVAL_BUDGET = 16 * 1024;

type NumberResult = { value: number } | { error: string };
export type RetrievalResult = { wire: string; chunks: EnvelopeChunk[] } | { error: string };

export interface RetrievalContinuation {
  command: string;
  args: string[];
}

function integer(value: string): number | null {
  if (!/^\d+$/.test(value)) return null;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : null;
}

/** Explicit CLI input is strict; invalid environment defaults are ignored. */
export function resolveRetrievalBudget(flag: string | undefined, legacyEnv?: string): NumberResult {
  if (flag !== undefined) {
    const value = integer(flag);
    return value !== null && value > 0
      ? { value }
      : { error: "--budget must be a positive whole number of bytes" };
  }
  for (const raw of [process.env.KB_RETRIEVAL_BUDGET, legacyEnv]) {
    if (raw === undefined) continue;
    const value = integer(raw);
    if (value !== null && value > 0) return { value };
  }
  return { value: DEFAULT_RETRIEVAL_BUDGET };
}

export function resolveRetrievalOffset(flag: string | undefined, name: string, minimum: number): NumberResult {
  if (flag === undefined) return { value: minimum };
  const value = integer(flag);
  return value !== null && value >= minimum
    ? { value }
    : { error: `--${name} must be a whole number greater than or equal to ${minimum}` };
}

export function continuation(
  command: string,
  args: string[],
  vaultPath: string,
  budget: number
): RetrievalContinuation {
  return { command, args: [...args, "--budget", String(budget), "-p", resolve(vaultPath)] };
}

export function retrievalWire(chunks: EnvelopeChunk[], policy: EnvelopePolicy): string {
  return writeEnvelope(buildEnvelope({ policy, chunks }));
}

export function checkWireBudget(wire: string, budget: number): string | null {
  const size = byteLength(wire);
  return size <= budget ? null : `output budget is too small; retry with --budget ${size}`;
}

interface FitInput {
  budget: number;
  policy: EnvelopePolicy;
  next: (offset: number) => RetrievalContinuation;
}

/** Keep exact complete source lines; metadata and framing count toward the cap. */
export function fitLineChunk(input: FitInput & { chunk: EnvelopeChunk }): RetrievalResult {
  const { chunk, budget, policy, next } = input;
  const full = retrievalWire([chunk], policy);
  if (byteLength(full) <= budget) return { wire: full, chunks: [chunk] };

  const lines = chunk.text.split("\n");
  const slice = (count: number): EnvelopeChunk => ({
    ...chunk,
    line_range: [chunk.line_range[0], chunk.line_range[0] + count - 1],
    text: lines.slice(0, count).join("\n"),
  });
  const wireFor = (count: number): string => retrievalWire([slice(count)], {
    ...policy,
    truncated: true,
    continuation: next(chunk.line_range[0] + count),
  });
  let lo = 0;
  let hi = lines.length - 1;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (byteLength(wireFor(mid)) <= budget) lo = mid;
    else hi = mid - 1;
  }
  if (lo === 0) {
    // Leave room for extra digits in the replacement budget's continuation.
    const required = byteLength(lines.length === 1 ? full : wireFor(1)) + 64;
    return { error: `line ${chunk.line_range[0]} in ${chunk.source} cannot fit the output budget; retry with --budget ${required}` };
  }
  return { wire: wireFor(lo), chunks: [slice(lo)] };
}

/** Paginate whole ordered results, retaining a replayable offset on every cut. */
export function fitChunkPage(input: FitInput & { chunks: EnvelopeChunk[]; offset: number }): RetrievalResult {
  const { chunks, offset, budget, policy, next } = input;
  if (offset > chunks.length) return { error: `--offset exceeds the ${chunks.length} available results` };
  const remaining = chunks.slice(offset);
  const full = retrievalWire(remaining, policy);
  if (byteLength(full) <= budget) return { wire: full, chunks: remaining };
  if (remaining.length === 0) return { error: checkWireBudget(full, budget)! };

  const wireFor = (count: number): string => retrievalWire(remaining.slice(0, count), {
    ...policy,
    truncated: true,
    continuation: next(offset + count),
  });
  let lo = 0;
  let hi = remaining.length - 1;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (byteLength(wireFor(mid)) <= budget) lo = mid;
    else hi = mid - 1;
  }
  if (lo === 0) {
    const first = remaining[0]!;
    const required = byteLength(remaining.length === 1 ? full : wireFor(1)) + 64;
    return { error: `result at ${first.source}:${first.line_range.join("-")} cannot fit the output budget; retry with --budget ${required}` };
  }
  return { wire: wireFor(lo), chunks: remaining.slice(0, lo) };
}
import { existsSync, realpathSync } from "node:fs";
import { join, relative } from "node:path";
import { defineCommand } from "citty";
import { resolveVaultPath } from "../lib/vault";
import type { EnvelopeChunk, EnvelopePolicy } from "../lib/envelope";
import { continuation, fitChunkPage, resolveRetrievalBudget, resolveRetrievalOffset } from "../lib/retrieval";
import { appendAccessLog } from "../lib/access-log";
import { assertGenuineScopeDir, PathUnsafeError } from "../lib/path-safety";
import { readWikiFileNoFollow, walkWiki } from "../lib/wiki-read";

const CONTEXT_LINES = 3;

function grepFile(
  path: string,
  needle: string
): Array<{ lineStart: number; lineEnd: number; snippet: string }> {
  const contents = readWikiFileNoFollow(path);
  if (contents === null) return [];
  const lines = contents.split("\n");
  const needleLc = needle.toLowerCase();
  const hits: Array<{ lineStart: number; lineEnd: number; snippet: string }> = [];
  for (let i = 0; i < lines.length; i++) {
    if (lines[i]!.toLowerCase().includes(needleLc)) {
      const start = Math.max(0, i - CONTEXT_LINES);
      const end = Math.min(lines.length - 1, i + CONTEXT_LINES);
      hits.push({
        lineStart: start + 1,
        lineEnd: end + 1,
        snippet: lines.slice(start, end + 1).join("\n"),
      });
    }
  }
  return hits;
}

export default defineCommand({
  meta: { name: "recall", description: "Search curated wiki pages" },
  args: {
    query: { type: "positional", description: "Search query", required: true },
    vaultPath: { type: "string", description: "Path to the vault directory", alias: ["p"] },
    budget: { type: "string", description: "Complete output byte budget (overrides KB_RETRIEVAL_BUDGET)" },
    offset: { type: "string", description: "Skip this many ordered search results (default 0)" },
  },
  async run({ args }) {
    const vaultPath = args.vaultPath ?? resolveVaultPath(process.cwd());
    const budget = resolveRetrievalBudget(args.budget);
    if ("error" in budget) {
      process.stderr.write(`error: ${budget.error}\n`);
      process.exit(1);
    }
    const offset = resolveRetrievalOffset(args.offset, "offset", 0);
    if ("error" in offset) {
      process.stderr.write(`error: ${offset.error}\n`);
      process.exit(1);
    }

    if (!existsSync(vaultPath)) {
      process.stderr.write(`error: vault not found at ${vaultPath}\n`);
      process.exit(1);
    }

    const wikiDir = join(vaultPath, "wiki");
    if (!existsSync(wikiDir)) {
      process.stderr.write(`error: wiki directory missing at ${wikiDir}\n`);
      process.exit(1);
    }

    try {
      assertGenuineScopeDir(wikiDir, vaultPath);
    } catch (err) {
      if (err instanceof PathUnsafeError) {
        process.stderr.write(`error: ${err.message}\n`);
        process.exit(1);
      }
      throw err;
    }

    const wikiReal = realpathSync(wikiDir);
    const chunks: EnvelopeChunk[] = [];
    const query = args.query;

    const paths: string[] = [];
    walkWiki(wikiDir, wikiReal, (path) => paths.push(path));
    for (const path of paths.sort()) {
      const hits = grepFile(path, query);
      const rel = relative(vaultPath, path);
      for (const h of hits) {
        chunks.push({
          source: rel,
          line_range: [h.lineStart, h.lineEnd],
          curation: "curated",
          text: h.snippet,
        });
      }
    }

    const policy: EnvelopePolicy =
      chunks.length === 0
        ? {
            trust: "curated",
            source_scope: "wiki",
            no_results: true,
            suggestions: ["Try: kb list-topics"],
          }
        : { trust: "curated", source_scope: "wiki" };

    const fitted = fitChunkPage({
      budget: budget.value,
      offset: offset.value,
      policy,
      chunks,
      next: (position) => continuation("recall", [query, "--offset", String(position)], vaultPath, budget.value),
    });
    if ("error" in fitted) {
      process.stderr.write(`error: ${fitted.error}\n`);
      process.exit(1);
    }
    const wire = fitted.wire;
    process.stdout.write(wire);

    try {
      await appendAccessLog({
        vaultPath,
        command: "recall",
        query,
        pages_returned: fitted.chunks.length,
        bytes_returned: new TextEncoder().encode(wire).length,
        exit_code: 0,
      });
    } catch {
      // logging must never fail the command
    }
  },
});

