): Promise<{ exitCode: number; stdout: string; stderr: string }> {
  const proc = Bun.spawn([process.execPath, CLI, "summarize", "--json", ...(options.args ?? []), env.manifest], {
    cwd: env.root,
    stdout: "pipe",
    stderr: "pipe",
    env: {
      ...process.env,
      KB_VAULT: env.vault,
      KB_SUMMARIZE_COMMAND: env.provider,
      KB_SUMMARIZE_ARGS: undefined,
